#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard guides you through the owner-only steps and checks each\n' "$DIM"
  printf '  result before continuing. Stop any time with Ctrl-C and resume manually.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

print_snippets() {
  cat <<'COMPOSE'
services:
  server:
    image: ghcr.io/OWNER/lander-server:TAG
    restart: unless-stopped
    env_file: .env
    environment:
      NODE_ENV: production
      PORT: "3000"
      DATABASE_PATH: /app/data/lander.sqlite
      OBJECT_STORE_DIR: /app/data/objects
    ports:
      - "127.0.0.1:3000:3000"
    volumes:
      - ./data:/app/data
COMPOSE

  cat <<'NGINX'
server {
    listen 443 ssl http2;
    server_name YOUR_HOSTNAME;

    # Configure certificate paths for the certificate manager you use.
    ssl_certificate     /etc/ssl/certs/YOUR_HOSTNAME.crt;
    ssl_certificate_key /etc/ssl/private/YOUR_HOSTNAME.key;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
NGINX

  cat <<'ENVVARS'
Production .env variable names (enter real values directly on the VPS):
  AUTH_SECRET (required; at least 32 characters)
  NODE_ENV=production
  RESEND_API_KEY, MAIL_FROM, MAIL_REPLY_TO (required for production email)
  DATABASE_PATH=data/lander.sqlite (optional; default)
  PORT=3000 (optional; default)
  OBJECT_STORE_DIR=data/objects (optional; default)
  R2_ACCOUNT_ID, R2_BUCKET, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY (optional; set all four together)
  HEARTBEAT_URL (optional)
  TRUSTED_EXTENSION_IDS (optional; Chrome store ID is already trusted)
  TRUST_ANY_EXTENSION_ORIGIN=false (optional; keep false in production)
  TRUST_PROXY_HEADER (optional; only if the proxy guarantees that header)
  REVIEWER_EMAIL and REVIEWER_CODE (optional; set together)
ENVVARS
}

check_dns() {
  local actual
  actual=$(dig +short A "$LANDER_HOSTNAME" | awk '/^[0-9.]+$/ { print; exit }')
  printf '  DNS A record: %s\n' "${actual:-not found}"
  [[ "$actual" == "$SERVER_IPV4" ]]
}

check_tls() {
  local output
  output=$(openssl s_client -connect "$LANDER_HOSTNAME:443" -servername "$LANDER_HOSTNAME" -verify 10 -verify_hostname "$LANDER_HOSTNAME" -verify_return_error </dev/null 2>&1) || {
    printf '%s\n' "$output" | tail -n 8
    return 1
  }
  if ! grep -q 'Verify return code: 0 (ok)' <<<"$output"; then
    printf '%s\n' "$output" | tail -n 8
    return 1
  fi
  say 'TLS certificate is valid and matches the hostname.'
}

run_wizard() {
  if [[ "${1:-}" == '--print-snippets' ]]; then
    print_snippets
    return
  fi

  TOTAL_STAGES=5
  banner 'Lander server stand-up'

  stage 'Choose the server hostname'
  say 'Use the HTTPS subdomain selected for the server in the owner checklist.'
  ask LANDER_HOSTNAME 'Server hostname (without https://):'
  [[ "$LANDER_HOSTNAME" != *'/'* && "$LANDER_HOSTNAME" != *' '* && -n "$LANDER_HOSTNAME" ]] || {
    warn 'Enter a hostname without a scheme, path, or spaces.'
    return 1
  }
  say "The server base URL will be https://$LANDER_HOSTNAME."
  pause 'Continue with this hostname?'

  stage 'Point DNS to the VPS'
  say 'In your DNS provider dashboard, open the zone for the hostname and add an A record.'
  step "Set the record name to the hostname label for $LANDER_HOSTNAME and the value to the VPS public IPv4 address."
  step 'Keep proxying disabled until the direct HTTPS origin check succeeds, if your DNS provider offers proxying.'
  ask SERVER_IPV4 'VPS public IPv4 address:'
  pause 'After saving the record, press Enter to verify DNS.'
  until check_dns; do
    warn 'The A record does not yet match the VPS address. Correct DNS, then try again.'
    pause 'Press Enter to check DNS again.'
  done

  stage 'Check VPS access'
  ask SSH_TARGET 'SSH destination (for example, deploy@hostname):'
  say 'This read-only command checks Docker, Compose, and free disk space:'
  printf '  ssh %q %q\n' "$SSH_TARGET" 'docker --version && docker compose version && df -h /'
  if confirm 'Run this exact read-only SSH command now?'; then
    ssh "$SSH_TARGET" 'docker --version && docker compose version && df -h /'
  else
    warn 'Run the displayed command yourself and confirm Docker, Compose, and disk space before continuing.'
    pause 'Press Enter after the VPS check is complete.'
  fi

  stage 'Configure the server and reverse proxy'
  say 'On the VPS, create the server directory and .env file. Type all secrets directly into that VPS file.'
  say 'Do not paste secrets into this wizard or your terminal command history.'
  print_snippets
  say 'Replace OWNER/TAG with the server image published for this repository and YOUR_HOSTNAME with the hostname.'
  say 'The compose example expects a published image; this repository checkout does not define its image name.'
  say 'Configure your certificate manager to provision TLS, then install the vhost with its actual certificate paths.'
  say 'Set TRUST_PROXY_HEADER only to a client-address header your reverse proxy overwrites safely.'
  pause 'After creating .env, compose configuration, and the HTTPS vhost on the VPS, press Enter to verify TLS.'
  until check_tls; do
    warn 'TLS is not valid for this hostname yet. Check the vhost, certificate paths, and firewall.'
    pause 'Press Enter to check TLS again.'
  done

  stage 'Check the public health endpoint'
  say "This read-only check requests https://$LANDER_HOSTNAME/health. It does not sign in or send account data."
  local health_response
  until health_response=$(curl --fail --silent --show-error "https://$LANDER_HOSTNAME/health") && [[ "$health_response" == '{"ok":true}' ]]; do
    warn 'The health check did not return HTTP 200. Check container logs and the proxy on the VPS.'
    pause 'Press Enter to check health again.'
  done
  say "Health response: $health_response"
  pause 'Confirm the server is ready.'
  finish
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  run_wizard "$@"
fi
